using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI Setup ---
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// --- Tools ---
var tools = new ResearchTools();
var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.TakeNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Agent ---
var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Given a topic, use the SearchWeb tool to find information, " +
    "use TakeNote to record key findings, and then produce a concise summary. " +
    "Search multiple times if needed to get comprehensive coverage. " +
    "Always call GetNotes at the end to review your notes before summarizing.")
{
    Tools = aiTools,
};

// --- Run ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

logger.LogInformation("Researching topic: {Topic}", topic);

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

string? finalResponse = null;

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && message.Content is { Length: > 0 })
    {
        Console.Write(message.Content);
        finalResponse = message.Content;
    }
}

Console.WriteLine();
Console.WriteLine();
Console.WriteLine("--- Notes Collected ---");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Implementations ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns a list of relevant snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing, Google, Brave) in production.
        return $"""
            Search results for "{query}":
            1. "{query}" is a widely discussed topic in current research and technology circles.
            2. Recent developments include advances in efficiency, scalability, and real-world applications.
            3. Key challenges involve ethical considerations, data quality, and accessibility.
            4. Industry leaders emphasize the importance of responsible development and open collaboration.
            5. Academic papers from 2025-2026 highlight breakthroughs in performance and cost reduction.
            """;
    }

    [Description("Save a research note for later reference. Use this to record key findings.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return "Saved notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

